use bex_vm_types::types::{InvalidProgram, LocalName};
use bex_vm_types::{ConstValue, DeclPath, GlobalIndex, Object, ObjectIndex, ObjectType, Program};
use indexmap::IndexMap;
use std::collections::{BTreeSet, HashSet};
use borsh::BorshDeserialize;
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicU64, Ordering};
static ALLOCATIONS: AtomicU64 = AtomicU64::new(0);
struct CountingAllocator;
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1,Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1,Ordering::Relaxed);
        unsafe { System.alloc_zeroed(layout) }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        ALLOCATIONS.fetch_add(1,Ordering::Relaxed);
        unsafe { System.realloc(ptr,layout,size) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        unsafe { System.dealloc(ptr,layout) }
    }
}
#[global_allocator]
static ALLOCATOR: CountingAllocator = CountingAllocator;
fn check(name: &str, program: &Program, results: &mut Vec<serde_json::Value>) {
    let eager = validate_original(program);
    let deferred = program.validate();
    assert_eq!(eager, deferred, "{name}");
    results.push(serde_json::json!({"case":name,"valid":eager.is_ok(),"error":eager.err().map(|error|error.to_string())}));
}
fn main() {
    let path=std::env::args().nth(1).unwrap();
    let bytes=std::fs::read(path).unwrap();
    let base=Program::deserialize(&mut bytes.as_slice()).unwrap();
    ALLOCATIONS.store(0,Ordering::Relaxed);
    validate_original(&base).unwrap();
    let eager_allocations=ALLOCATIONS.load(Ordering::Relaxed);
    ALLOCATIONS.store(0,Ordering::Relaxed);
    base.validate().unwrap();
    let deferred_allocations=ALLOCATIONS.load(Ordering::Relaxed);
    let mut results=Vec::new();
    check("valid",&base,&mut results);
    let mut program=base.clone(); program.root=u32::MAX;
    check("invalid root",&program,&mut results);
    let invalid_object=ObjectIndex::from_raw(base.objects.len()+1);
    for index in 0..base.packages.len() {
        let mut program=base.clone(); program.packages[index].init=Some(invalid_object);
        check(&format!("package {index} invalid init"),&program,&mut results);
        let mut program=base.clone(); program.packages[index].test_init=Some(invalid_object);
        check(&format!("package {index} invalid test init"),&program,&mut results);
        if !base.packages[index].edges.is_empty() {
            let mut program=base.clone(); program.packages[index].edges[0].target=u32::MAX;
            check(&format!("package {index} invalid edge"),&program,&mut results);
            let mut program=base.clone(); let duplicate=program.packages[index].edges[0].clone(); program.packages[index].edges.push(duplicate);
            check(&format!("package {index} duplicate edge"),&program,&mut results);
        }
        for table in ["classes","enums","interfaces","type aliases"] {
            let mut program=base.clone();
            let package=&mut program.packages[index];
            let map=match table {"classes"=>&mut package.classes,"enums"=>&mut package.enums,"interfaces"=>&mut package.interfaces,_=>&mut package.type_aliases};
            if let Some(value)=map.values_mut().next() {
                *value=invalid_object;
                check(&format!("package {index} invalid {table}"),&program,&mut results);
            }
        }
        if !base.packages[index].globals.is_empty() {
            let mut program=base.clone(); program.packages[index].slot_base=GlobalIndex::from_raw(base.globals.len()+1);
            check(&format!("package {index} invalid slot"),&program,&mut results);
        }
        if !base.packages[index].impl_rules.is_empty() {
            let mut program=base.clone(); let rules=program.packages[index].impl_rules.first().unwrap().1.clone(); program.packages[index].impl_rules.clear(); program.packages[index].impl_rules.insert(invalid_object,rules);
            check(&format!("package {index} invalid impl interface"),&program,&mut results);
        }
    }
    let mut program=base.clone(); program.init_order.push(u32::MAX);
    check("invalid init order",&program,&mut results);
    let mut program=base.clone(); program.init_order=vec![0,0];
    check("duplicate init order",&program,&mut results);
    let mut program=base.clone(); program.init_order=vec![0];
    check("wrong init set",&program,&mut results);
    let mut program=base.clone(); program.globals.push(ConstValue::Object(invalid_object));
    check("invalid global object",&program,&mut results);
    let mut program=base.clone();
    for object in &mut program.objects.0 {
        if let Object::Function(function)=object { function.bytecode.constants.push(ConstValue::Object(invalid_object)); break; }
    }
    check("invalid function operand",&program,&mut results);
    let mut program=base.clone();
    for object in &mut program.objects.0 {
        if let Object::Class(class)=object { if let Some(method)=class.methods.values_mut().next() { method.function=invalid_object; break; } }
    }
    check("invalid class method",&program,&mut results);
    let mut program=base.clone();
    for object in &mut program.objects.0 {
        if let Object::Interface(interface)=object { if let Some(method)=interface.methods.first_mut() { method.default=Some(invalid_object); break; } }
    }
    check("invalid interface default",&program,&mut results);
    let mut program=base.clone(); let mut changed=false;
    for object in &mut program.objects.0 {
        bex_vm_types::head_walk::visit_object_heads_mut(object,&mut |head| {
            if !changed { *head=bex_vm_types::TypeHead::unresolved_operand(invalid_object); changed=true; }
        });
    }
    assert!(changed);
    check("unbound type head",&program,&mut results);
    let mut program=base.clone();
    program.objects.0.push(Object::GenericFunction(bex_vm_types::GenericFunction {
        function: GlobalIndex::from_raw(base.globals.len()+1),
        type_args: Box::default(), runtime_package: bex_vm_types::HeapPtr::null(),
    }));
    check("invalid generic cell",&program,&mut results);
    assert!(results.iter().skip(1).all(|case|case["valid"]==false));
    println!("{}",serde_json::json!({"checks":results,"valid_program_allocation_requests":{"eager":eager_allocations,"two_pass":deferred_allocations}}));
}

fn validate_original(program: &Program) -> Result<(), InvalidProgram> {
        let invalid = |message: String| InvalidProgram(message);
        let object_count = program.objects.len();
        let object = |index: ObjectIndex, role: &str| -> Result<&Object, InvalidProgram> {
            program.objects.get(index.raw()).ok_or_else(|| {
                invalid(format!(
                    "{role} names object {} of {object_count}",
                    index.raw()
                ))
            })
        };
        let function =
            |index: ObjectIndex, role: &str, is_body: bool| -> Result<(), InvalidProgram> {
                match object(index, role)? {
                    Object::Function(function) if function.is_interface_body == is_body => Ok(()),
                    other => Err(invalid(format!(
                        "{role} names a {:?} object where {} is required",
                        ObjectType::of(other),
                        if is_body {
                            "an interface body"
                        } else {
                            "a function"
                        }
                    ))),
                }
            };

        let package_count = program.packages.len();
        if program.root as usize >= package_count {
            return Err(invalid(format!(
                "the root is package {} of {package_count}",
                program.root
            )));
        }
        for package in &program.packages {
            let name = &package.name;
            let mut edge_names = HashSet::new();
            for edge in &package.edges {
                if edge.target as usize >= package_count {
                    return Err(invalid(format!(
                        "package `{name}` edge `{}` names package {} of {package_count}",
                        edge.name, edge.target
                    )));
                }
                if !edge_names.insert(&edge.name) {
                    return Err(invalid(format!(
                        "package `{name}` reaches two packages as `{}`",
                        edge.name
                    )));
                }
            }
            let declarations = |kind: &str,
                                table: &IndexMap<LocalName, ObjectIndex>,
                                holds: fn(&Object) -> bool|
             -> Result<(), InvalidProgram> {
                for (item, &index) in table {
                    let role = format!("package `{name}` {kind} `{item}`");
                    let pooled = object(index, &role)?;
                    if !holds(pooled) {
                        return Err(invalid(format!(
                            "{role} names a {:?} object",
                            ObjectType::of(pooled)
                        )));
                    }
                }
                Ok(())
            };
            declarations("class", &package.classes, |object| {
                matches!(object, Object::Class(_))
            })?;
            declarations("enum", &package.enums, |object| {
                matches!(object, Object::Enum(_))
            })?;
            declarations("interface", &package.interfaces, |object| {
                matches!(object, Object::Interface(_))
            })?;
            declarations("type alias", &package.type_aliases, |object| {
                matches!(object, Object::TypeAlias(_))
            })?;
            for (&interface, rules) in &package.impl_rules {
                let role = format!("package `{name}` implements object {}", interface.raw());
                if !matches!(object(interface, &role)?, Object::Interface(_)) {
                    return Err(invalid(format!("{role}, which is not an interface")));
                }
                for rule in rules {
                    if rule.interface_head != interface {
                        return Err(invalid(format!(
                            "{role} with a rule whose head is object {}",
                            rule.interface_head.raw()
                        )));
                    }
                    for (method, body) in &rule.methods {
                        function(body.fqn, &format!("{role}, method `{method}`,"), true)?;
                    }
                }
            }
            if let Some(init) = package.init {
                function(init, &format!("package `{name}` `$init`"), false)?;
            }
            if let Some(test_init) = package.test_init {
                function(test_init, &format!("package `{name}` `$init_test`"), false)?;
            }
            for (path, &ordinal) in &package.globals {
                if !path.owns_global_slot() {
                    return Err(invalid(format!(
                        "package `{name}` slots {path}, which owns no cell"
                    )));
                }
                let slot = package.slot_base.raw() + ordinal as usize;
                let Some(cell) = program.globals.get(slot) else {
                    return Err(invalid(format!(
                        "package `{name}` slots {path} at cell {slot} of {}",
                        program.globals.len()
                    )));
                };
                match path {
                    DeclPath::Function(_) | DeclPath::InterfaceBody(_) => {
                        let ConstValue::Object(index) = cell else {
                            return Err(invalid(format!(
                                "package `{name}` cell for {path} holds no object"
                            )));
                        };
                        function(
                            *index,
                            &format!("package `{name}` cell for {path}"),
                            matches!(path, DeclPath::InterfaceBody(_)),
                        )?;
                    }
                    DeclPath::Let(_) => {}
                    DeclPath::Class(_)
                    | DeclPath::Enum(_)
                    | DeclPath::Interface(_)
                    | DeclPath::TypeAlias(_) => {
                        unreachable!("a type owns no cell: checked above")
                    }
                }
            }
        }

        let with_init: BTreeSet<usize> = program
            .packages
            .iter()
            .enumerate()
            .filter(|(_, package)| package.init.is_some())
            .map(|(ordinal, _)| ordinal)
            .collect();
        let mut ordered = BTreeSet::new();
        for &ordinal in &program.init_order {
            let ordinal = ordinal as usize;
            if ordinal >= package_count {
                return Err(invalid(format!(
                    "the init order names package {ordinal} of {package_count}"
                )));
            }
            if !ordered.insert(ordinal) {
                return Err(invalid(format!(
                    "the init order names package {ordinal} twice"
                )));
            }
        }
        if ordered != with_init {
            return Err(invalid(
                "the init order is not exactly the packages with an `$init`".to_string(),
            ));
        }

        for (slot, cell) in program.globals.iter().enumerate() {
            if let ConstValue::Object(index) = cell {
                object(*index, &format!("cell {slot}"))?;
            }
        }

        for (index, pooled) in program.objects.iter().enumerate() {
            let role = format!("object {index}");
            let mut failure = None;
            bex_vm_types::head_walk::visit_object_heads(pooled, &mut |head| {
                if failure.is_some() {
                    return;
                }
                let tag = head.tag();
                let bound = tag
                    .static_index()
                    .and_then(|declaration| program.objects.get(declaration))
                    .is_some_and(|declaration| declaration.declaration_tag() == Some(tag));
                if !bound {
                    failure = Some(invalid(format!(
                        "{role} carries a head with tag {tag:?}, which names no declaration"
                    )));
                }
            });
            if let Some(failure) = failure {
                return Err(failure);
            }
            match pooled {
                Object::Function(function) => {
                    bex_vm_types::relink::visit_index_operands_ref(function, |operand| {
                        if failure.is_some() {
                            return;
                        }
                        let in_range = match operand {
                            bex_vm_types::relink::IndexOperandRef::Object(index) => {
                                index.raw() < object_count
                            }
                            bex_vm_types::relink::IndexOperandRef::Global(slot) => {
                                slot.raw() < program.globals.len()
                            }
                        };
                        if !in_range {
                            failure = Some(invalid(format!(
                                "{role} (function `{}`) references an operand outside the program",
                                function.name
                            )));
                        }
                    });
                    if let Some(failure) = failure {
                        return Err(failure);
                    }
                    for instruction in &function.bytecode.instructions {
                        match instruction {
                            bex_vm_types::bytecode::Instruction::LoadCurrentPackage(package)
                                if *package >= package_count =>
                            {
                                return Err(invalid(format!(
                                    "{role} (function `{}`) loads package {package} of \
                                     {package_count}",
                                    function.name
                                )));
                            }
                            // The VM reads the dispatch value at `args_offset +
                            // self_arg`; past `nargs` that is past the stack.
                            bex_vm_types::bytecode::Instruction::VirtualCall {
                                nargs, self_arg, ..
                            } if self_arg >= nargs => {
                                return Err(invalid(format!(
                                    "{role} (function `{}`) dispatches a virtual call on \
                                     argument {self_arg} of {nargs}",
                                    function.name
                                )));
                            }
                            _ => {}
                        }
                    }
                    if let Some((table, _)) = function
                        .bytecode
                        .switch_tables
                        .iter()
                        .enumerate()
                        .find(|(_, table)| !table.dispatch.is_dispatchable())
                    {
                        return Err(invalid(format!(
                            "{role} (function `{}`) switch table {table} is not solved",
                            function.name
                        )));
                    }
                }
                Object::Interface(interface) => {
                    for method in &interface.methods {
                        if let Some(default) = method.default {
                            function(
                                default,
                                &format!("{role} (interface) default of `{}`", method.name),
                                true,
                            )?;
                        }
                    }
                }
                Object::Class(class) => {
                    for (name, method) in &class.methods {
                        function(
                            method.function,
                            &format!("{role} (class) method `{name}`"),
                            false,
                        )?;
                    }
                }
                Object::GenericFunction(generic)
                    if generic.function.raw() >= program.globals.len() =>
                {
                    return Err(invalid(format!(
                        "{role} (generic value) references cell {} of {}",
                        generic.function.raw(),
                        program.globals.len()
                    )));
                }
                _ => {}
            }
        }
        Ok(())
    }

