                        function(
                            default,
                            &format!("{role} (interface) default of `{}`", method.name),
                            true,
                        )?;
                    }
                }
            }
            Object::Class(class) => {
                for (name, method) in &class.methods {
                    function(
                        method.function,
                        &format!("{role} (class) method `{name}`"),
                        false,
                    )?;
                }
            }
